def elx_series_pass_regulator(Vin=None, Vz=None, Rs=None, RL=None, beta=None, VBE=None):
    """Zener-referenced series-pass (emitter-follower) regulator. The output voltage, load, base, Zener and resistor currents and the pass-transistor dissipation of a regulator in which a Zener diode biased through Rs sets the base of an emitter-follower pass transistor.
    Formula: V_{out} = V_Z - V_{BE},\\quad I_Z = \\frac{V_{in} - V_Z}{R_S} - \\frac{I_L}{\\beta+1}
    Inputs:
        Vin: unregulated input
        Vz: Zener voltage
        Rs: Zener bias resistor
        RL: load resistance
        beta: current gain of the pass transistor
        VBE: base-emitter voltage
    Outputs: Vout (output voltage Vz - VBE), I_L (load current), I_B (base current), I_z (Zener current), I_Rs (current in Rs), P_Q (pass-transistor dissipation)
    See also: help("elx_series_pass_regulator")
    """
    given = {k: v for k, v in dict(Vin=Vin, Vz=Vz, Rs=Rs, RL=RL, beta=beta, VBE=VBE).items() if v is not None}
    return _P.solve("elx_series_pass_regulator", **given)

def elx_setup_hold_timing(T=None, tcq=None, tpd=None, tsu=None, tskew=None, tccq=None, tcd=None, th=None):
    """Flip-flop setup and hold slack, maximum clock frequency. The setup slack, hold slack, maximum clock frequency and a verdict for a register-to-register path from clock-to-Q, logic delays, setup and hold times and clock skew (positive when the capture clock is late).
    Formula: T \\ge t_{cq} + t_{pd} + t_{su} - t_{skew},\\quad t_{ccq} + t_{cd} \\ge t_h + t_{skew}
    Inputs:
        T: clock period
        tcq: maximum clock-to-Q delay
        tpd: maximum logic delay
        tsu: setup time
        tskew: clock skew, capture minus launch
        tccq: minimum (contamination) clock-to-Q
        tcd: minimum (contamination) logic delay
        th: hold time
    Outputs: setup_slack (setup slack), hold_slack (hold slack), f_max (maximum clock frequency), verdict (meets timing, setup violation, hold violation or both)
    See also: help("elx_setup_hold_timing")
    """
    given = {k: v for k, v in dict(T=T, tcq=tcq, tpd=tpd, tsu=tsu, tskew=tskew, tccq=tccq, tcd=tcd, th=th).items() if v is not None}
    return _P.solve("elx_setup_hold_timing", **given)

def elx_shockley_diode_current(Is=None, n=None, VD=None, T=None):
    """Diode current from the Shockley equation. The current of a pn-junction diode at a terminal voltage from its saturation current, ideality factor and temperature (forward or reverse).
    Formula: I_D = I_S\\left(e^{V_D/nV_T} - 1\\right)
    Inputs:
        Is: saturation current
        n: ideality (emission) factor, 1 to 2
        VD: diode voltage (negative for reverse bias)
        T: junction temperature
    Outputs: ID (diode current), VT (thermal voltage)
    See also: help("elx_shockley_diode_current")
    """
    given = {k: v for k, v in dict(Is=Is, n=n, VD=VD, T=T).items() if v is not None}
    return _P.solve("elx_shockley_diode_current", **given)

